{"command":"$ErrorActionPreference='Stop'
$ud = 'C:\Users\spay\AppData\Local\Yandex\YandexBrowser\User Data\Profile 2'
$sess = Get-ChildItem (Join-Path $ud 'Sessions') -File | Sort-Object LastWriteTime -Descending | Select-Object -First 1
$fs = [System.IO.File]::Open($sess.FullName, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
try { $bytes = New-Object byte[] $fs.Length; [void]$fs.Read($bytes, 0, $fs.Length) } finally { $fs.Close() }
$txt = [System.Text.Encoding]::Unicode.GetString($bytes)
$urls = [regex]::Matches($txt, 'https?://[^\x00-\x1F\x22\x27<>]{6,300}') | ForEach-Object { $_.Value } | Select-Object -Unique
'=== glaido ==='; $urls | Where-Object { $_ -match 'glaido' }
'=== github ==='; $urls | Where-Object { $_ -match 'github\.com' } | Select-Object -First 15
'=== hf settings ==='; $urls | Where-Object { $_ -match 'huggingface\.co/settings' }
'=== local/dev hosts ==='; $urls | Where-Object { $_ -match '(?i)localhost|127\.0\.0\.1|:3000|:5173|:8080' } | Select-Object -First 15","description":"Inspect candidate settings URLs in detail"}

{"command":"$ErrorActionPreference='Stop'
$cands = @(
 'C:\Users\spay\Documents\hermes-agent-2026.7.20\apps\desktop',
 'C:\Users\spay\Documents\PR\screenpipe-main\apps\screenpipe-app-tauri',
 'C:\Users\spay\Documents\qwen\pr1\cowork\apps\qwen-cowork',
 'C:\Users\spay\Documents\HermesWorld'
)
foreach ($c in $cands) {
  "=== $c ==="
  if (-not (Test-Path $c)) { '  MISSING'; continue }
  $pj = Join-Path $c 'package.json'
  if (Test-Path $pj) {
    $j = Get-Content $pj -Raw | ConvertFrom-Json
    '  name: ' + $j.name
    $deps = @()
    if ($j.dependencies) { $deps = $j.dependencies.PSObject.Properties.Name | Where-Object { $_ -match '^(react|next|vue|svelte|tailwindcss|@tauri-apps)' } }
    '  deps: ' + ($deps -join ', ')
  } else { '  no package.json' }
  $sf = Get-ChildItem $c -Recurse -File -Include '*.tsx','*.jsx','*.vue' -ErrorAction SilentlyContinue | Where-Object { $_.FullName -notmatch 'node_modules' }
  '  ui files: ' + $sf.Count
}","description":"Characterize candidate frontend codebases"}

{"command":"$ErrorActionPreference='Stop'
